# ruff: noqa: E501
"""Report section "SA2.4 and SA2.7 vs. baseline" (English prose, tables generated by code)."""

import numpy as np
import pandas as pd

from firecal.stages.harmonize.evaluate import MAIN_PAIRS, FoldOut, coverage_table, score_table
from firecal.stages.harmonize.metrics import wape
from firecal.stages.harmonize.ml import ML_METHODS, MLResult
from firecal.stages.harmonize.ml_criterion import (
    BOOT_LEVEL,
    BOOT_SEED,
    N_BOOT,
    Verdict,
    bootstrap_diff,
    evaluate_criterion,
)

CANDIDATES = ("lgb_cell", "lgb_block")
DIRECTION = {
    "viirs_to_modis": "SA2.4: VIIRS (S-NPP) -> MODIS-equivalent",
    "modis_to_viirs": "SA2.7: MODIS -> VIIRS-equivalent (inverse series)",
}
NAMES = {"sf": "SA2.2 factor"} | ML_METHODS


def _fmt():  # noqa: D103
    from firecal.stages.harmonize.report import md_table, num, pct

    return md_table, num, pct


def verdicts(ml: MLResult, sf_folds: list[FoldOut]) -> dict[tuple[str, str], Verdict]:
    allml = [f for fs in ml.folds.values() for f in fs]
    out = {}
    for pair in MAIN_PAIRS:
        for method in CANDIDATES:
            out[pair, method] = evaluate_criterion(sf_folds, allml, pair, method)
    return out


def _years(folds, pair, scheme, method) -> dict[int, FoldOut]:
    return {f.test_year: f for f in folds if (f.pair, f.scheme, f.method) == (pair, scheme, method)}


def _pooled(fs: list[FoldOut], years) -> tuple[np.ndarray, np.ndarray]:
    return (
        np.concatenate([fs[y].obs.ravel() for y in years]),
        np.concatenate([fs[y].pred.ravel() for y in years]),
    )


def zero_tree_check(allf: list[FoldOut], pair: str) -> list[dict]:
    """Zero-tree (offset only) vs SA2.2 block totals pooled over the leave-one-year-out test years."""
    sf = _years(allf, pair, "loyo", "sf")
    rows = []
    for method in ("zero_cell", "zero_block"):
        z = _years(allf, pair, "loyo", method)
        years = sorted(set(z) & set(sf))
        if not years:
            continue
        zb = sum(z[y].pred.sum(axis=0) for y in years)
        sb = sum(sf[y].pred.sum(axis=0) for y in years)
        rel = np.abs(zb - sb) / np.where(sb > 0, sb, np.nan)
        big = sb >= 1000
        o, p = _pooled(sf, years)
        _, pz = _pooled(z, years)
        rows.append(
            {
                "method": method,
                "total_ratio": float(zb.sum() / sb.sum()),
                "max_rel_big": float(np.nanmax(rel[big])) if big.any() else float("nan"),
                "n_over_1": int(np.nansum((rel > 0.01) & big)),
                "n_big": int(big.sum()),
                "wape_zero": wape(o, pz),
                "wape_sf": wape(o, p),
            }
        )
    return rows


def ml_section(ml: MLResult, sf_folds: list[FoldOut], prev: MLResult | None = None) -> list[str]:
    md_table, num, pct = _fmt()
    allml = [f for fs in ml.folds.values() for f in fs]
    allf = sf_folds + allml
    scores = score_table(allf)
    ver = verdicts(ml, sf_folds)

    def row(pair, scheme, method, year, level):
        s = scores[
            (scores["pair"] == pair)
            & (scores["scheme"] == scheme)
            & (scores["method"] == method)
            & (scores["test_year"].astype(str) == str(year))
            & (scores["level"] == level)
        ]
        return s.iloc[0] if len(s) else None

    L = ["## SA2.4 and SA2.7 vs. baseline", ""]
    L += [
        "LightGBM on top of the SA2.2 scale factor (the factor enters as an offset: `init_score = log(f_block x source + eps)`), "
        "with the same metrics, the same folds (leave-one-year-out with a 6-month gap, and rolling origin) and the same "
        "aggregation to block-month and block-year as SA2.2. Everything is retrospective. The publication criterion was fixed in "
        "`plan/02-harmonization.md` before the run and was not touched after seeing results.",
        "",
        "### What was run",
        "",
        "- **Cell model** (main candidate): rows of 0.1° cell x month x day/night where the **source** is active in the cell or its 3x3 neighborhood "
        '(the design said "some sensor active"; with the target observed at test time the row set would leak the target and, training only on '
        "rows with an active target, would bias upward the rows without a source; the change is an implementation decision, not a change of the criterion). Target "
        "detections in cell-months with no source in their 3x3 neighborhood are out of reach (like source = 0 in SA2.2): "
        + ", ".join(
            f"{DIRECTION[p].split(':')[0]} {pct(ml.meta[p]['unreachable_share'])} of the target detections ({ml.meta[p]['cell_rows']:,} rows)"
            for p in MAIN_PAIRS
            if p in ml.meta
        )
        + ".",
        "- **Features** (all from the source, known at prediction time): count, FRP, FRP per detection, count of the other part of the day (day/night), day/night share, "
        "is-night, 3x3 count, source total in the block-month and month of the year. Ablations: with Terra/Aqua share (MODIS as source only: "
        "terra and aqua separately, FRP per satellite and Terra share; it does not exist in VIIRS -> MODIS, which stays the same) and with lat/lon. "
        "The main candidate is the base model without Terra/Aqua share and without lat/lon; the ablations are not candidates.",
        "- **Offset:** smoothed source (3x3 on rows without a source) and rescaled per block-month-day/night to preserve the source total: without that "
        "rescaling the smoothing adds mass and with zero trees SA2.2 would not be reproduced. Factors of the training rows: out-of-sample "
        "(inner leave-one-year-out, with a gap); those of the test rows: fitted on the outer training set.",
        "- **Block-month model:** same ideas on block-month x day/night rows (heavily regularized, 3-7 leaves), second candidate.",
        "- **Objective and selection:** Poisson (Tweedie 1.2 only in the block-month model grid). Hyperparameters by block-month WAPE with inner leave-one-year-out inside "
        "each outer training set; learning rate 0.1 for the cell and 0.05 for the block, `num_threads` = 2, fixed seed, `deterministic`.",
        f"- **Grid (reduced for time):** cell: one structure ({ml.cell_grid[0].num_leaves} leaves, minimum {ml.cell_grid[0].min_data} rows per leaf, L2 {ml.cell_grid[0].l2:g}) with "
        f"{'/'.join(str(i) for i in ml.cell_grid[0].iters)} trees to choose from; block-month: {len(ml.block_grid)} structures x "
        f"{'/'.join(str(i) for i in ml.block_grid[0].iters)} trees. The evaluation design (nested, same folds) was not reduced. "
        "The ablations reuse the configuration chosen by the base cell model in the same fold.",
        "- **Intervals:** SA2.2 nested conformal scheme (`intervals.py`) on the LightGBM point predictions (out-of-sample residuals of the "
        "chosen configuration); no LightGBM quantile regression (optional diagnostic, not run).",
        "- **Discarded run and leaf cap (not in the earlier design):** the first full run gave, in the SA2.7 cell model, predictions of the order of 1e18: "
        "leaves with Newton steps of tens on the log scale on rows without a source in their day/night part (offset at the `eps` floor) but with target detections. "
        "`max_delta_step = 1` was added (a cap on each leaf output, at most 0.1 on the log scale per tree with learning rate 0.1) **after** that first run, to fix a numerical failure; "
        "it applies to both directions and both models, and was not in the design fixed before running. The criterion, features, folds and grid did not change. "
        "The SA2.4 results of that run had already been seen before the fix; the cap was not chosen by measuring it against them (single value, no others tried). "
        "In addition, a guard stops the run if any prediction (outer or inner) is non-finite or exceeds 100 times the observed value.",
        f"- **Time and memory:** {ml.seconds / 60:.1f} min of wall-clock time for this part, one process per direction (2 threads each); summed peak memory "
        f"(PSS of the processes) {ml.peak_mb:.0f} MB.",
        "",
    ]

    # --- Verdict ---
    L += ["### Publication criterion and verdict", ""]
    L += [
        "LightGBM is published in a direction only if the candidate meets all seven conditions (the 6th only in SA2.7): "
        "1) leave-one-year-out block-month WAPE at least 1 point lower than SA2.2 and block-year not higher; 2) lower block-month WAPE in at least 10 of 14 test years; "
        "3) improvement of the same sign under rolling origin; 4) total |bias| not worse than SA2.2's + 0.5 points and the worst year not worse; "
        "5) block-month Poisson deviance not worse; 6) block-month conformal coverage 80 +/- 5 % and relative width not larger; "
        f"7) the paired bootstrap interval (years and blocks resampled separately, {N_BOOT} resamples, seed {BOOT_SEED}, {BOOT_LEVEL * 100:.0f} % percentiles) "
        'of the block-month WAPE difference excludes zero. Interpretations fixed before the run: the "worst year" is a leave-one-year-out test year; '
        'coverage and width are the block-month ones (block-year is reported, not a condition); "excludes zero" requires an upper limit < 0. '
        "The verdict of a direction is that of the main candidate (cell); the block-month model has its own, separately.",
        "",
    ]
    for pair in MAIN_PAIRS:
        for method in CANDIDATES:
            v = ver[pair, method]
            tag = "main candidate" if method == "lgb_cell" else "second candidate"
            L.append(f"**{DIRECTION[pair]} - {NAMES[method]} ({tag}): {v.text}.**")
            L.append("")
            L += md_table(
                ["Condition", "Result", "Detail"],
                [[c.name, "met" if c.passed else "NOT met", c.detail] for c in v.conditions],
            )
            L.append("")
    L.append(
        "Verdict by direction (main candidate): "
        + "; ".join(f"{DIRECTION[p].split(':')[0]}: {ver[p, 'lgb_cell'].text}" for p in MAIN_PAIRS)
        + ". If it does not beat the factor, SA2.2 is published."
    )
    L.append("")

    for pair in MAIN_PAIRS:
        L += [f"### {DIRECTION[pair]}", ""]
        # headline pooled
        rows = []
        cand_years = sorted(
            set(_years(allf, pair, "loyo", "lgb_cell")) & set(_years(allf, pair, "loyo", "sf"))
        )
        sf_y = _years(allf, pair, "loyo", "sf")
        ref_roll = set(_years(allf, pair, "rolling", "lgb_cell")) & set(_years(allf, pair, "rolling", "sf"))
        for method in (
            "sf",
            "lgb_cell",
            "lgb_block",
            "lgb_cell_ta",
            "lgb_cell_ll",
            "zero_cell",
            "zero_block",
        ):
            a = row(pair, "loyo", method, "all", "block-month")
            if a is None:
                continue
            b = row(pair, "loyo", method, "all", "block-year")
            my = _years(allf, pair, "loyo", method)
            ys = sorted(set(my) & set(sf_y))
            won = (
                "-"
                if method == "sf" or method.startswith("zero")
                else f"{sum(wape(my[y].obs, my[y].pred) < wape(sf_y[y].obs, sf_y[y].pred) for y in ys)} of {len(ys)}"
            )
            ry, rs = _years(allf, pair, "rolling", method), _years(allf, pair, "rolling", "sf")
            common = sorted(set(ry) & set(rs) & ref_roll)
            roll = pct(wape(*_pooled(ry, common))) if common else "-"
            rows.append(
                [
                    NAMES[method],
                    pct(a["bias"], True),
                    pct(a["wape"]),
                    pct(b["wape"]),
                    num(a["mae"], 2),
                    num(a["deviance"], 2),
                    won,
                    roll,
                ]
            )
        L += md_table(
            [
                "Method",
                "Bias b-month",
                "WAPE b-month",
                "WAPE b-year",
                "MAE b-month",
                "Deviance b-month",
                "Years with lower b-month WAPE than SA2.2",
                "WAPE b-month rolling origin",
            ],
            rows,
        )
        L += [
            "",
            f"Leave-one-year-out, {len(cand_years)} test years, all pooled. The rolling-origin column uses the same years in every row (those of the cell model; the first one, "
            "with a single training year, does not allow an inner leave-one-year-out and is omitted).",
            "",
        ]
        # per year
        rows = []
        for y in cand_years:
            vals = []
            for method in ("sf", "lgb_cell", "lgb_block"):
                a, b = row(pair, "loyo", method, y, "block-month"), row(pair, "loyo", method, y, "block-year")
                vals.append((a, b))
            rows.append(
                [y]
                + [pct(v[0]["wape"]) for v in vals]
                + [pct(v[1]["wape"]) for v in vals]
                + [pct(v[0]["bias"], True) for v in vals]
                + ["cell" if vals[1][0]["wape"] < vals[0][0]["wape"] else "SA2.2"]
            )
        L += ["Error by test year (leave-one-year-out):", ""]
        L += md_table(
            [
                "Year",
                "WAPE b-month SA2.2",
                "cell",
                "block",
                "WAPE b-year SA2.2",
                "cell",
                "block",
                "Bias SA2.2",
                "cell",
                "block",
                "Lower b-month (SA2.2 vs cell)",
            ],
            rows,
        )
        L.append("")

        # intervals
        cov_sf = coverage_table(allf, method="sf")
        covs = {m: coverage_table(allf, method=m) for m in CANDIDATES}
        rows = []
        for level in ("block-month", "block-year"):
            for method, tab in (
                ("sf", cov_sf),
                ("lgb_cell", covs["lgb_cell"]),
                ("lgb_block", covs["lgb_block"]),
            ):
                r = tab[
                    (tab["pair"] == pair)
                    & (tab["scheme"] == "loyo")
                    & (tab["interval"] == "conformal")
                    & (tab["level"] == level)
                    & (tab["test_year"].astype(str) == "all")
                ]
                if len(r):
                    r = r.iloc[0]
                    rows.append(
                        [
                            level,
                            NAMES[method],
                            int(r["n"]),
                            pct(r["coverage"]),
                            num(r["rel_width"], 3),
                            pct(r["out_share"]),
                        ]
                    )
        L += ["Nested conformal intervals (nominal 80 %, leave-one-year-out, rows with source > 0):", ""]
        L += md_table(["Level", "Method", "n", "Coverage", "Relative width", "Out-of-reach detections"], rows)
        L.append("")

        # zero-tree
        zt = zero_tree_check(allf, pair)
        if zt:
            L += [
                "Zero-tree check (the offset alone should reproduce the SA2.2 block totals; within ~1 %). "
                "Per block, only blocks with at least 1000 detections predicted by SA2.2 over the pooled test years are examined; "
                "the difference comes from the `eps` floor of the offset (it adds a small mass on rows without a source):",
                "",
            ]
            L += md_table(
                [
                    "Model",
                    "Total / SA2.2 total",
                    "Max. relative difference per block",
                    "Blocks with diff. > 1 %",
                    "WAPE b-month zero trees",
                    "WAPE b-month SA2.2",
                ],
                [
                    [
                        NAMES[z["method"]],
                        num(z["total_ratio"], 4),
                        pct(z["max_rel_big"]),
                        f"{z['n_over_1']} of {z['n_big']}",
                        pct(z["wape_zero"]),
                        pct(z["wape_sf"]),
                    ]
                    for z in zt
                ],
            )
            L.append("")

    # --- config / importance ---
    L += ["### Configuration chosen by test year (leave-one-year-out)", ""]
    rows = []
    for dg in sorted((d for d in ml.diags if d.scheme == "loyo"), key=lambda d: (d.pair, d.test_year)):
        rows.append(
            [
                DIRECTION[dg.pair].split(":")[0],
                dg.test_year,
                f"{dg.cell_cfg} / {dg.cell_iters} trees",
                f"{dg.block_cfg} / {dg.block_iters} trees",
            ]
        )
    L += md_table(["Direction", "Year", "Cell", "Block-month"], rows)
    L += ["", "### Feature importance (gain, base cell model)", ""]
    L += [
        "Gain normalized to 1 per fold and averaged over the leave-one-year-out folds. It describes which features the model used; it is not a causal effect "
        "nor a permutation importance.",
        "",
    ]
    for pair in MAIN_PAIRS:
        imp = [d.importance for d in ml.diags if d.pair == pair and d.scheme == "loyo"]
        if not imp:
            continue
        mean = pd.Series({k: np.mean([i[k] for i in imp]) for k in imp[0]}).sort_values(ascending=False)
        L += [f"{DIRECTION[pair]}:", ""]
        L += md_table(["Feature", "Mean gain"], [[k, pct(v)] for k, v in mean.items()])
        L.append("")
    low = {}
    for dg in ml.diags:
        if dg.scheme == "loyo":
            low.setdefault(dg.pair, [0, 0])
            low[dg.pair][1] += 1
            low[dg.pair][0] += dg.cell_iters == min(ml.cell_grid[0].iters)
    L += ["### Notes on the fit and the bias", ""]
    L += [
        f"- Trees at the lower edge of the grid ({min(ml.cell_grid[0].iters)}), cell model, leave-one-year-out: "
        + "; ".join(f"{DIRECTION[p].split(':')[0]} {v[0]} of {v[1]} folds" for p, v in sorted(low.items()))
        + ". If the choice falls on the edge, the grid may have been too short toward fewer trees.",
        "- Zero trees: the check table gives the actual number. The `eps` floor of the offset adds, as an upper bound, eps x cell rows = "
        + "; ".join(
            f"{DIRECTION[p].split(':')[0]} {0.001 * ml.meta[p]['cell_rows']:,.0f} detections over the whole period (all rows, test and training years)"
            for p in MAIN_PAIRS
            if p in ml.meta
        )
        + ", against the SA2.2 block totals; this is the cause of the difference from the ~1 % of the design in small blocks. `eps` was not touched after seeing test results.",
        "- The cell model bias may be structural (**unverified**): it is trained with the targets inside the candidate rows but evaluated against all targets, "
        "and between 2.6 % (SA2.4) and 6.2 % (SA2.7) of the target detections fall outside the rows. It is a possible explanation and does not change the verdict.",
        "",
    ]
    if prev is not None:
        a = _years([f for fs in ml.folds.values() for f in fs], "viirs_to_modis", "loyo", "lgb_cell")
        b = _years([f for fs in prev.folds.values() for f in fs], "viirs_to_modis", "loyo", "lgb_cell")
        ys = sorted(set(a) & set(b))
        rows = [
            [
                y,
                pct(wape(b[y].obs, b[y].pred)),
                pct(wape(a[y].obs, a[y].pred)),
                f"{(wape(a[y].obs, a[y].pred) - wape(b[y].obs, b[y].pred)) * 100:+.2f}",
            ]
            for y in ys
        ]
        mx = max(abs(float(r[3])) for r in rows) if rows else float("nan")
        L += ["### SA2.4 cell: change due to the leaf cap (first run vs. this one)", ""]
        L += md_table(["Year", "WAPE b-month first run", "WAPE b-month with cap", "Change (points)"], rows)
        L += [
            "",
            f"Maximum absolute change: {mx:.2f} points. "
            + (
                "Less than ~0.2 points was expected: **it moved more, flagged.**"
                if mx >= 0.2
                else "Within expectations (< ~0.2 points)."
            ),
            "",
        ]
    L += [
        "Notes: the cause of any difference between models is **unverified**; the tables only describe. The results hold for Argentina, 2012-02 to 2025-12 "
        "(S-NPP/MODIS overlap) and for the count after the default `FilterConfig`. The inverse series estimates counts VIIRS would have recorded per cell-month, "
        "with uncertainty; it does not locate individual hot spots.",
        "",
    ]
    return L


# --- SA2.9: SA2.7 with and without the MCD64A1 burned-area variable ---------------------------------------

PAIR_29 = "modis_to_viirs"
WITHOUT, WITH = "lgb_cell", "lgb_cell_ba"


def relabel_burned(ml: MLResult) -> list[FoldOut]:
    """Folds of the run that used the burned-area variable, under their own method names."""
    out = []
    for fs in ml.folds.values():
        for f in fs:
            if f.method in ("lgb_cell", "zero_cell"):
                f.method = f.method + "_ba"
                out.append(f)
    return out


def sa29_report(
    sf_folds: list[FoldOut],
    without: MLResult,
    with_: MLResult,
    info: dict,
    run_date,
    cmd: str = "firecal harmonize burned-ml",
) -> str:
    """Report text of SA2.9. `info`: manifest summary and burned-area statistics (see `burned_info`)."""
    md_table, num, pct = _fmt()
    base = [f for fs in without.folds.values() for f in fs if f.method == "lgb_cell"]
    ba = relabel_burned(with_)
    ba_cell = [f for f in ba if f.method == WITH]
    sf = [f for f in sf_folds if f.pair == PAIR_29]
    allf = sf + base + ba_cell
    names = {
        "sf": "SA2.2 factor",
        WITHOUT: "LightGBM cell, without burned area",
        WITH: "LightGBM cell, with burned area",
    }
    v0 = evaluate_criterion(sf, base, PAIR_29, WITHOUT)
    v1 = evaluate_criterion(sf, ba_cell, PAIR_29, WITH)
    scores = score_table(allf)

    def row(scheme, method, year, level):
        s = scores[
            (scores["pair"] == PAIR_29)
            & (scores["scheme"] == scheme)
            & (scores["method"] == method)
            & (scores["test_year"].astype(str) == str(year))
            & (scores["level"] == level)
        ]
        return s.iloc[0] if len(s) else None

    sf_y = _years(allf, PAIR_29, "loyo", "sf")
    years = sorted(set(_years(allf, PAIR_29, "loyo", WITH)) & set(sf_y))
    rolling_years = sorted(
        set(_years(allf, PAIR_29, "rolling", WITH))
        & set(_years(allf, PAIR_29, "rolling", WITHOUT))
        & set(_years(allf, PAIR_29, "rolling", "sf"))
    )
    L = ["# SA2.9: MCD64A1 burned area as an SA2.7 variable", ""]
    d_bm = (
        row("loyo", WITH, "all", "block-month")["wape"] - row("loyo", WITHOUT, "all", "block-month")["wape"]
    )
    pt, lo, hi = bootstrap_diff(_years(allf, PAIR_29, "loyo", WITH), _years(allf, PAIR_29, "loyo", WITHOUT))
    L += [
        f"Generated by `{cmd}` on {run_date.isoformat()}. Everything is retrospective.",
        "",
        "## Result",
        "",
        f"- SA2.7 verdict without the variable (reproduction of `reports/02/baselines.md`): **{v0.text}**; "
        f"with the variable: **{v1.text}**. The publication criterion of `plan/02-harmonization.md` was not touched.",
        f"- Leave-one-year-out block-month WAPE: SA2.2 {pct(row('loyo', 'sf', 'all', 'block-month')['wape'])}, "
        f"LightGBM without {pct(row('loyo', WITHOUT, 'all', 'block-month')['wape'])}, "
        f"with {pct(row('loyo', WITH, 'all', 'block-month')['wape'])} "
        f"(with minus without {d_bm * 100:+.2f} points; paired bootstrap {pt * 100:+.2f} [{lo * 100:+.2f}; {hi * 100:+.2f}] points, 95 %).",
        f"- Conditions met: without {sum(c.passed for c in v0.conditions)} of {len(v0.conditions)}, "
        f"with {sum(c.passed for c in v1.conditions)} of {len(v1.conditions)}.",
        '- The `harmonized` layer stays with SA2.2 unless the "with" verdict above says otherwise.',
        "",
        "## Data",
        "",
    ]
    L += [f"- {x}" for x in info["data_lines"]]
    L += ["", "## What was run", ""]
    L += [
        "- **Variable** (km2, both from the 0.1 degree grid built here): `ba_cell` = MCD64A1 burned area in the cell and "
        "`ba_n3` = in the cell and its 8 neighbours, for the same calendar month. It does not depend on the sensors, "
        "exists from 2000-11 (it is available in 2000-2011, MODIS only) and is zero where no burned pixel was mapped.",
        "- **Everything else identical** to the SA2.7 cell model of `baselines.md`: candidate rows (source active in the cell or its 3x3), "
        "offset `log(f x source + eps)`, features (9 base features), grid (one Poisson structure, 25/50/100 trees), "
        "`max_delta_step = 1`, folds (leave-one-year-out with a 6-month gap and rolling origin), seeds, nested conformal intervals, "
        'metrics and the seven-condition criterion. Only the two columns above are added in the "with" run; the block-month model '
        "and the ablations are not rerun (the variable is a cell feature).",
        "- **Candidate rows do not change:** a burned cell without any source detection in its 3x3 is still not a row, so the variable "
        "cannot reach fires the source did not flag anywhere nearby; it only informs rows that already exist. "
        f"Share of the burned area of the SA2.7 months that falls in a candidate cell-month: {pct(info['in_rows_share'])} "
        f"({info['burned_in_rows']:,.0f} of {info['burned_total']:,.0f} km2).",
        f"- **Time and memory:** without {without.seconds / 60:.1f} min, with {with_.seconds / 60:.1f} min of wall-clock time "
        f"(run as parallel processes, 2 threads each); peak summed PSS {max(without.peak_mb, with_.peak_mb):.0f} MB.",
        "",
        "## SA2.7 error with and without the variable",
        "",
    ]
    rows = []
    for method in ("sf", WITHOUT, WITH):
        a, b = row("loyo", method, "all", "block-month"), row("loyo", method, "all", "block-year")
        my = _years(allf, PAIR_29, "loyo", method)
        ys = sorted(set(my) & set(sf_y))
        won = (
            "-"
            if method == "sf"
            else f"{sum(wape(my[y].obs, my[y].pred) < wape(sf_y[y].obs, sf_y[y].pred) for y in ys)} of {len(ys)}"
        )
        ry, rs = _years(allf, PAIR_29, "rolling", method), _years(allf, PAIR_29, "rolling", "sf")
        roll = pct(wape(*_pooled(ry, rolling_years))) if rolling_years and method != "sf" else "-"
        rolls = pct(wape(*_pooled(rs, rolling_years))) if rolling_years else "-"
        rows.append(
            [
                names[method],
                pct(a["wape"]),
                pct(b["wape"]),
                pct(a["bias"], True),
                num(a["deviance"], 2),
                won,
                roll if method != "sf" else rolls,
            ]
        )
    L += md_table(
        [
            "Method",
            "WAPE block-month",
            "WAPE block-year",
            "Bias (total, block-month)",
            "Deviance block-month",
            "Years with lower block-month WAPE than SA2.2",
            "WAPE block-month, rolling origin",
        ],
        rows,
    )
    L += [
        "",
        f"Leave-one-year-out over {len(years)} test years ({years[0]}-{years[-1]}), all pooled; rolling origin over the {len(rolling_years)} years "
        "that every row scores (the SA2.2 row shows its own value on those years).",
        "",
    ]
    # coverage
    cov = {m: coverage_table(allf, method=m) for m in ("sf", WITHOUT, WITH)}
    rows = []
    for level in ("block-month", "block-year"):
        for m in ("sf", WITHOUT, WITH):
            t = cov[m]
            r = t[
                (t["pair"] == PAIR_29)
                & (t["scheme"] == "loyo")
                & (t["interval"] == "conformal")
                & (t["level"] == level)
                & (t["test_year"].astype(str) == "all")
            ]
            if len(r):
                r = r.iloc[0]
                rows.append([level, names[m], int(r["n"]), pct(r["coverage"]), num(r["rel_width"], 3)])
    L += ["Nested conformal intervals (nominal 80 %, leave-one-year-out, rows with source > 0):", ""]
    L += md_table(["Level", "Method", "n", "Coverage", "Relative width"], rows)
    L.append("")
    # per year
    rows = []
    for y in years:
        vals = [row("loyo", m, y, "block-month") for m in ("sf", WITHOUT, WITH)]
        rows.append([y] + [pct(v["wape"]) for v in vals] + [pct(v["bias"], True) for v in vals])
    L += ["Block-month WAPE and bias by test year (leave-one-year-out):", ""]
    L += md_table(
        ["Year", "WAPE SA2.2", "WAPE without", "WAPE with", "Bias SA2.2", "Bias without", "Bias with"], rows
    )
    L.append("")
    # criterion
    L += ["## Publication criterion (fixed before the SA2.7 run; unchanged)", ""]
    for v, label in ((v0, "without the variable"), (v1, "with the variable")):
        L.append(f"**SA2.7 LightGBM cell, {label}: {v.text}.**")
        L.append("")
        L += md_table(
            ["Condition", "Result", "Detail"],
            [[c.name, "met" if c.passed else "NOT met", c.detail] for c in v.conditions],
        )
        L.append("")
    # importance
    imp: dict[str, list[float]] = {}
    for dg in with_.diags:
        if dg.scheme == "loyo":
            for k, val in dg.importance.items():
                imp.setdefault(k, []).append(val)
    if imp:
        L += [
            "## Importance of the variable in the model (gain share, mean over the leave-one-year-out folds)",
            "",
        ]
        L += md_table(
            ["Feature", "Mean gain share"],
            [[k, pct(float(np.mean(v)))] for k, v in sorted(imp.items(), key=lambda kv: -np.mean(kv[1]))],
        )
        L += [
            "",
            "Gain share shows how much the trees use a variable, not that it improves the out-of-sample error.",
            "",
        ]
    L += ["## Limits and open items", ""]
    L += [f"- {x}" for x in info["limits"]]
    L.append("")
    return "\n".join(L)


def burned_info(
    burned: pd.DataFrame, long: pd.DataFrame, manifest: dict, meta: dict, parquet_sha: str
) -> dict:
    """Facts about the burned-area data for the SA2.9 report, computed from the files (nothing typed by hand)."""
    from firecal.io.burned_area import LAST_YM, PIX_M, PIXEL_AREA_KM2, SHORT_NAME, VERSION

    _, _, pct = _fmt()

    gr = {k: v for k, v in manifest["granules"].items() if "sha256" in v}
    bad = {k: v for k, v in manifest["granules"].items() if "sha256" not in v}
    tiles = sorted({(v["h"], v["v"]) for v in gr.values()})
    yms = sorted({v["ym"] for v in gr.values()})
    per_month = pd.Series([v["ym"] for v in gr.values()]).value_counts()
    full = len(tiles)
    short = per_month[per_month < full]
    ym_lbl = lambda ym: f"{ym // 12}-{ym % 12 + 1:02d}"  # noqa: E731
    all_months = range(yms[0], LAST_YM[0] * 12 + LAST_YM[1])
    missing_months = [m for m in all_months if m not in set(yms)]
    # Burned area in cell-months where neither Terra nor Aqua flagged a hot spot in the cell.
    modis = long[long["satellite"].isin(["terra", "aqua"])]
    mk = set(
        zip(modis["cell_id"].astype(np.int64).tolist(), modis["ym"].astype(np.int64).tolist(), strict=True)
    )
    flagged = np.array(
        [
            (int(c), int(m)) in mk
            for c, m in zip(burned["cell_id"].to_numpy(), burned["ym"].to_numpy(), strict=True)
        ]
    )
    modis_ym = set(modis["ym"].astype(int))
    in_modis_months = burned["ym"].isin(modis_ym).to_numpy()
    tot = float(burned.loc[in_modis_months, "burned_km2"].sum())
    unflagged = float(burned.loc[in_modis_months & ~flagged, "burned_km2"].sum())
    unm_km2 = float(burned["unmapped_px"].sum() * PIXEL_AREA_KM2)
    by_year = burned.assign(year=burned["ym"] // 12).groupby("year")["burned_km2"].sum()
    m = next(iter(meta.values()))
    data_lines = [
        f"**Product:** {SHORT_NAME} Collection 6.1 (version {VERSION}), MODIS/Terra+Aqua Burned Area Monthly L3 Global 500 m "
        "SIN grid, layer `Burn Date`; DOI 10.5067/MODIS/MCD64A1.061; archive: NASA LP DAAC. Granules found with NASA CMR "
        "(`short_name=MCD64A1`, `version=061`, bounding box of the ADM2 boundaries) and downloaded from `data.lpdaac.earthdatacloud.nasa.gov`.",
        f"**Period:** {ym_lbl(yms[0])} to {ym_lbl(yms[-1])} ({len(yms)} months with data). The product starts in 2000-11; "
        "January-October 2000 do not exist.",
        f"**Tiles and granules:** {len(gr):,} granules, {len(tiles)} MODIS tiles (h{min(t[0] for t in tiles)}-h{max(t[0] for t in tiles)}, "
        f"v{min(t[1] for t in tiles)}-v{max(t[1] for t in tiles)}), sha256 and size of every file in `data/raw/mcd64a1/manifest.json`; "
        f"failed or missing granules: {len(bad)}. `data/` is not in git.",
        f"**Gridding:** pixel centres from the MODIS sinusoidal grid formula (sphere radius 6,371,007.181 m, tile 1,111,950.52 m, 2,400 x 2,400 "
        f"pixels, pixel {PIX_M:.2f} m), counted per 0.1 degree cell with the same `cell_ids` as the FIRMS grid, month taken from the granule, "
        f"clipped to the union of the geoBoundaries ADM2 polygons (simplified geometry, same as the FIRMS area clip). **Pixel area used: "
        f'{PIXEL_AREA_KM2:.4f} km2** (the sinusoidal grid is equal-area, so every pixel has this area; the product\'s "500 m" is {PIX_M:.1f} m). '
        "Pixels with burn date 1-366 count as burned; -1 (unmapped, insufficient data) is kept as `unmapped_px`; -2 (water) and 0 are not counted. "
        f"Output `data/interim/burned/mcd64a1_0.1.parquet`: {len(burned):,} cell-months with burned area or unmapped pixels, sha256 `{parquet_sha[:16]}...`.",
        f"**Burned area in Argentina (clipped):** {by_year.min():,.0f} to {by_year.max():,.0f} km2 per year over {int(by_year.index.min())}-{int(by_year.index.max())} "
        f"(partial years: 2000 starts in November); total {float(burned['burned_km2'].sum()):,.0f} km2. Not compared with an independent figure (unverified).",
        f"**Cell-months where MODIS flagged nothing:** {unflagged / tot * 100:.1f} % of the burned area ({unflagged:,.0f} of {tot:,.0f} km2, "
        "months with Terra or Aqua data) lies in cell-months with no Terra or Aqua hot spot in the same 0.1 degree cell. This is the share the "
        "variable could in principle add information about; it says nothing yet about whether SA2.7 improves.",
        '**Licence:** the CMR collection record (read 2026-11-15) lists access constraints "None" and no use constraints; the citation is '
        "Giglio, Justice, Boschetti and Roy, MODIS/Terra+Aqua Burned Area Monthly L3 Global 500m SIN Grid V061, NASA LP DAAC, "
        "DOI 10.5067/MODIS/MCD64A1.061. The LP DAAC / NASA data-use policy text was not read here, so the licence terms are **unverified**; "
        "access to the files needs a free NASA Earthdata login. Cite the DOI if the data are redistributed or shown.",
    ]
    if len(missing_months):
        data_lines.append(
            f"**Months without any granule:** {', '.join(ym_lbl(x) for x in missing_months[:12])}"
            + (" ..." if len(missing_months) > 12 else "")
            + "."
        )
    else:
        data_lines.append("**Months without any granule:** none within the period.")
    if len(short):
        data_lines.append(
            f"**Months with fewer than {full} tiles:** {len(short)} (first: "
            + ", ".join(f"{ym_lbl(int(k))} ({int(v)})" for k, v in short.sort_index().head(8).items())
            + "). The missing tile-months count as no burned area in the variable."
        )
    else:
        data_lines.append(f"**Tiles per month:** every month has all {full} tiles.")
    data_lines.append(
        f"**Unmapped pixels** (`-1`, insufficient observations): {unm_km2:,.0f} km2-months in total inside Argentina; "
        "they are not used as a feature."
    )
    limits = [
        "The candidate rows of the cell model are those with source activity in the 3x3 neighbourhood; burned area that is far from any source detection "
        "is not a row and therefore cannot be predicted. Opening the row set to burned cells would change the training rows and the unreachable share, "
        "and with it the comparison; it was not done here (it would need its own criterion fixed beforehand).",
        "The variable is MODIS-derived; the algorithm also uses MODIS active-fire detections to guide the mapping (from the product description, not re-read here: unverified), "
        "so it is probably not independent of the MODIS hot spots. It exists in 2000-2011, the MODIS-only period.",
        "Burned area is a monthly, cell-level amount while the target is counts of detections: a single large burn can sit in cells whose count is small. "
        "No Landsat or other burned-area product was used (SA0.8 access unconfirmed).",
        f"Target detections with no source in their 3x3 (out of reach of the model, unchanged by the variable): {pct(m['unreachable_share'])}. "
        "The with and without runs use the same seed, folds and hyperparameter grid, so differences come from the two added columns; with one seed and 14 test years, "
        "differences below the bootstrap interval are not distinguishable from noise.",
    ]
    return {
        "data_lines": data_lines,
        "limits": limits,
        "in_rows_share": m["burned_km2_in_rows"] / m["burned_km2_total"]
        if m.get("burned_km2_total")
        else float("nan"),
        "burned_in_rows": m.get("burned_km2_in_rows", float("nan")),
        "burned_total": m.get("burned_km2_total", float("nan")),
    }
